package interium.fabric;
import net.minecraft.client.gui.screen.Screen;import net.minecraft.text.Text;
public final class PerformanceScreen extends PrismSettingsScreen {
 public PerformanceScreen(Screen p){super(p,Text.literal("Performance / Minecraft"));}
 @Override protected void init(){super.init();mode("Стекло","perf.quality",new String[]{"Lite","Balanced","Quality"},1);button("FPS: "+client.getCurrentFps()+" · лимит: "+client.options.getMaxFps().getValue()+" · VSync: "+client.options.getEnableVsync().getValue(),()->{});flag("LOD дальних мобов / предметов","perf.entities",false);slider("Мобы: дистанция отрисовки","perf.entityRange",64,16,256,8);slider("Предметы: дистанция отрисовки","perf.itemRange",32,8,128,4);
 button("Снять лимит FPS / VSync (по нажатию)",()->{remember();client.options.getEnableVsync().setValue(false);client.options.getMaxFps().setValue(260);client.options.write();});button("Мир 8 чанков / симуляция 6 (по нажатию)",()->{remember();client.options.getViewDistance().setValue(8);client.options.getSimulationDistance().setValue(6);client.options.write();});button("Вернуть сохранённые видеонастройки",()->{if(!DeltaVisualSettings.flag("perf.saved",false))return;client.options.getEnableVsync().setValue(DeltaVisualSettings.flag("perf.oldVsync",true));client.options.getMaxFps().setValue((int)DeltaVisualSettings.number("perf.oldFps",120,10,260));client.options.getViewDistance().setValue((int)DeltaVisualSettings.number("perf.oldView",12,2,32));client.options.getSimulationDistance().setValue((int)DeltaVisualSettings.number("perf.oldSim",12,2,32));client.options.write();DeltaVisualSettings.set("perf.saved",false);});}
 private void remember(){if(DeltaVisualSettings.flag("perf.saved",false))return;DeltaVisualSettings.set("perf.saved",true);DeltaVisualSettings.set("perf.oldVsync",client.options.getEnableVsync().getValue());DeltaVisualSettings.set("perf.oldFps",client.options.getMaxFps().getValue());DeltaVisualSettings.set("perf.oldView",client.options.getViewDistance().getValue());DeltaVisualSettings.set("perf.oldSim",client.options.getSimulationDistance().getValue());DeltaVisualSettings.save();}
}
